pub fn list_outcome_to_record(value: &jig_domain_link::ListOutcome) -> Result<jig_protocol_worker_wire::v22::ListOutcome, jig_protocol_worker_wire::v22::Problem> {
    Ok(match value {
        jig_domain_link::ListOutcome::Listed(held) => jig_protocol_worker_wire::v22::ListOutcome::Listed(jig_protocol_worker_wire::v22::ListedRows { rows: {
                let source = held;
                let count = match u32::try_from(source.len()) { Ok(count) => count, Err(_error) => return Err(jig_protocol_worker_wire::v22::paths::LISTED_ROWS_ROWS.problem(skein_codec::Reason::Bound)) };
                let mut translated = skein_lib::List::with_capacity(count);
                for item in source.as_ref() {
                    let converted = list_row_to_record(item)?;
                    assert!(translated.push(converted).is_ok(), "one output per source item");
                }
                translated
            } }),
        jig_domain_link::ListOutcome::Failed(held) => jig_protocol_worker_wire::v22::ListOutcome::Failed(jig_protocol_worker_wire::v22::ListFailureValue { value: list_failed_to_record(held) }),
    })
}

